# Generated by build.py from recipe.yml for recipe smtp-forward-mail-with-an-alias. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'help.eml'), "From: form@example.com`nTo: support@example.com`nSubject: Cannot log in`n`nPlease reset my password.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'form@example.com:formpass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mail-alias', '"support@example.com=ann@example.com,bob@example.com"', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u form@example.com:formpass --mail-from form@example.com --mail-rcpt support@example.com -T help.eml smtp://127.0.0.1:8080/example.com
curl.exe -sS --retry 10 --retry-all-errors --retry-delay 1 -o NUL -u bob@example.com:bobpass "imap://127.0.0.1:8081/INBOX;UID=1"
try { curl.exe -sS -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Cannot%20log%20in%22" --next -sS -u bob@example.com:bobpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Cannot%20log%20in%22" } finally { Stop-Process $server0 }
